mapper.select:
	select	
		FILE_ID, ITEM_ID, FILE_NM, FILE_EXT, MEDIA_TP, FILE_SIZE, SAVE_PATH, SAVE_FILE_NM, DWN_CNT, REG_ID, REG_DT, UPD_ID, UPD_DT
	from		
		JCMS_FILE_ITEM
	where
		1=1
		  and FILE_ID = #{fileId} 
		 and ITEM_ID = #{itemId} 
	 order by ${sort} ${sortOrd} 
     limit #{start}, #{length}

mapper.insert:
insert into JCMS_FILE_ITEM (
	FILE_ID,
	FILE_NM,
	FILE_EXT,
	MEDIA_TP,
	FILE_SIZE,
	SAVE_PATH,
	SAVE_FILE_NM,
	DWN_CNT,
	REG_ID,
	REG_DT
) values (
	#{fileId,jdbcType=NUMERIC}
	, #{fileNm}
	, #{fileExt}
	, #{mediaTp}
	, #{fileSize}
	, #{savePath}
	, #{saveFileNm}
	, 0
	, #{regId}
	, SYSDATE()
)

mapper.delete:
update JCMS_FILE_ITEM set
	FILE_ID = #{fileId}
where 
	ITEM_ID = #{itemId,jdbcType=VARCHAR}
